<script setup lang="ts" generic="Row">
/**
 * Table with sorting, selection, pagination, loading and empty states (`design/components/data-table.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/data-table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, type VNode } from 'vue'

import { agentMember, useListening, useTrackedSlots } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/data-table.module.css'
import Button from '../controls/Button.vue'
import Checkbox from '../controls/Checkbox.vue'
import EmptyState, { type EmptyStateProps } from './EmptyState.vue'
import Inline from '../layout/Inline.vue'
import Skeleton from './Skeleton.vue'
import Table, { type SortDirection } from './Table.vue'
import TableBody from './TableBody.vue'
import TableCell from './TableCell.vue'
import TableHead from './TableHead.vue'
import TableHeader from './TableHeader.vue'
import TableRow from './TableRow.vue'

export interface DataTableColumn<Row> {
  key: string
  header: string
  /** Defaults to `String(row[key])`, the common case. */
  cell?: (row: Row) => VNode | string
  sortable?: boolean
  numeric?: boolean
}

export interface DataTableSort {
  key: string
  direction: SortDirection
}

export interface DataTableRowDetail<Row> {
  row: Row
  /**
   * Closes this row's detail. When focus is inside the detail it moves to the row's
   * disclosure first, because a focused element that leaves the page leaves focus on
   * the page itself. It does nothing for a row that is not open.
   */
  close: () => void
}

export interface DataTableMessages {
  /** The bulk bar's count. */
  selected: (count: number) => string
  selectAll: string
  /** The row checkbox's name when `getRowLabel` is not supplied. */
  selectRow: string
  /**
   * Names a row's disclosure, from what `getRowName` returns for the row, and names
   * the expansion column's header, called with `undefined`. Optional, so messages
   * written for a table without `rowDetail` still type-check.
   */
  detailsLabel?: (rowName: string | undefined) => string
}

export interface DataTableProps<Row> {
  columns: DataTableColumn<Row>[]
  data: Row[]
  /**
   * The rows open at first, while the table holds the set. The set keeps the id of a row that
   * leaves `data`, so a row that comes back with its page is still open.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * Required, because a list without a designed empty state has a bug.
   */
  emptyState: EmptyStateProps
  /**
   * The open rows by id. Controlled when given; without it the table holds the set.
   */
  expanded?: ReadonlySet<string>
  getRowId: (row: Row) => string
  /**
   * The whole name of a row's checkbox ("Select Invoice 12"), so a screen reader does not hear
   * "Select row" on every row. Only the checkbox reads it.
   */
  getRowLabel?: (row: Row) => string
  /**
   * The row's own name ("Invoice 12"). `messages.detailsLabel` names the row's disclosure from
   * it ("Details for Invoice 12"). It is not `getRowLabel`, which is a whole control's name: a
   * disclosure named from it would read "Details for Select Invoice 12".
   */
  getRowName?: (row: Row) => string
  /**
   * Whether a row has a detail. A row it refuses has an empty cell in the expansion column and
   * never draws a detail row, whatever `expanded` holds. A function that draws cannot report
   * that it drew nothing, so the table asks this before it draws the disclosure. Without it
   * every row has one.
   */
  isRowExpandable?: (row: Row) => boolean
  label: string
  loading?: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: DataTableMessages
  /**
   * Passing it turns selection on, even as an empty set.
   */
  selection?: ReadonlySet<string>
  /**
   * Controlled; the type allows exactly one sorted column.
   */
  sort?: DataTableSort
  stickyHeader?: boolean
}

defineOptions({ name: 'DataTable', inheritAttrs: false })

const props = withDefaults(defineProps<DataTableProps<Row>>(), {
  isRowExpandable: undefined,
  loading: false,
  messages: () => ({
    selected: (count: number) => `${count} selected`,
    selectAll: 'Select all',
    selectRow: 'Select row',
  }),
  stickyHeader: undefined,
})
const emit = defineEmits<{
  expandedChange: [next: ReadonlySet<string>]
  rowClick: [row: Row]
  selectionChange: [next: ReadonlySet<string>]
  sortChange: [sort: DataTableSort]
}>()
const callerSlots = defineSlots<{
  bulkActions?: (props: Record<string, never>) => unknown
  pagination?: (props: Record<string, never>) => unknown
  rowDetail?: (props: DataTableRowDetail<Row>) => unknown
}>()
const slots = useTrackedSlots(callerSlots)
const uid = useId()
const listening = useListening()
const ownExpanded = ref(props.defaultExpanded ?? new Set<string>())
const root = useTemplateRef<HTMLElement>('root')
const selectable = computed(() => props.selection !== undefined)
const expandable = computed(() => slots.rowDetail)
const open = computed(() => props.expanded ?? ownExpanded.value)
const canExpand = computed(
  () =>
    (row: Row): boolean =>
      props.isRowExpandable?.(row) ?? true,
)
const detailsLabel = computed(
  () =>
    props.messages.detailsLabel ??
    ((rowName: string | undefined): string =>
      rowName === undefined ? 'Details' : `Details for ${rowName}`),
)
const span = computed(() => props.columns.length + (selectable.value ? 1 : 0) + 1)
const ids = computed(() => props.data.map((row) => props.getRowId(row)))
const selectedCount = computed(() => props.selection?.size ?? 0)
const selectedHere = computed(() => ids.value.filter((id) => props.selection?.has(id)).length)
const allSelected = computed(
  () => selectable.value && ids.value.length > 0 && selectedHere.value === ids.value.length,
)
const someSelected = computed(() => selectedHere.value > 0 && !allSelected.value)
const headerChecked = computed(() =>
  allSelected.value ? true : someSelected.value ? 'indeterminate' : false,
)
const bar = computed(() => selectable.value && selectedCount.value > 0)
const empty = computed(() => !props.loading && props.data.length === 0)
const skeletons = computed(() => Array.from({ length: 5 }, (_, index) => index))
const cellOf = computed(() => (column: DataTableColumn<Row>, row: Row): VNode | string => {
  if (column.cell !== undefined) return column.cell(row)
  const value = (row as Record<string, unknown>)[column.key]
  return value === undefined || value === null ? '' : String(value)
})
const sortTo = computed(() => (column: DataTableColumn<Row>): DataTableSort => ({
  key: column.key,
  direction: props.sort?.key === column.key && props.sort?.direction === 'asc' ? 'desc' : 'asc',
}))
const toggleAll = computed(() => () => {
  if (props.selection === undefined) return
  const next = new Set(props.selection)
  for (const id of ids.value) {
    if (allSelected.value) next.delete(id)
    else next.add(id)
  }
  emit('selectionChange', next)
})
const toggleRow = computed(() => (id: string) => {
  if (props.selection === undefined) return
  const next = new Set(props.selection)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  emit('selectionChange', next)
})
const toggleExpanded = computed(() => (id: string) => {
  const next = new Set(open.value)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  ownExpanded.value = next
  emit('expandedChange', next)
})
const closeDetail = computed(() => (id: string) => {
  if (!open.value.has(id)) return
  const element = root.value as HTMLElement | null
  const detailId = CSS.escape(`${uid}-detail-${ids.value.indexOf(id)}`)
  if (element?.querySelector(`#${detailId}`)?.matches(':focus-within') === true)
    element.querySelector<HTMLElement>(`[aria-controls="${detailId}"]`)?.focus()
  const next = new Set(open.value)
  next.delete(id)
  ownExpanded.value = next
  emit('expandedChange', next)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'DataTable',
    element: () => root.value,
    state: () => ({
      'sort-key': props.sort?.key ?? null,
      'sort-direction': props.sort?.direction ?? '',
      columns: props.columns.map((column) => ({
        id: column.key,
        label: column.header,
        ...(column.sortable === true ? {} : { disabled: true }),
      })),
      selection: [...(props.selection ?? [])],
      expanded: [...open.value],
      loading: props.loading,
    }),
    actions: {
      'sort-ascending': {
        argument: 'id',
        run: (value) =>
          (props.sort?.key === value && props.sort?.direction === 'asc') ||
          emit('sortChange', { key: value, direction: 'asc' }),
      },
      'sort-descending': {
        argument: 'id',
        run: (value) =>
          (props.sort?.key === value && props.sort?.direction === 'desc') ||
          emit('sortChange', { key: value, direction: 'desc' }),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.table"
    :data-loading="loading ? '' : undefined"
    :data-empty="empty ? '' : undefined"
    :aria-busy="loading ? true : undefined"
    data-member="data-table"
  >
    <!-- bulk bar -->
    <div v-if="bar" :class="styles.bulkBar">
      <Inline :gap="4" align="center" justify="between" :wrap="true">
        <!-- count -->
        <span :class="styles.bulkCount" aria-live="polite">
          {{ messages.selected(selectedCount) }}
        </span>
        <Inline v-if="$slots.bulkActions" :gap="3" align="center" :wrap="true">
          <slot name="bulkActions" />
        </Inline>
      </Inline>
    </div>
    <EmptyState
      v-if="empty"
      :icon="emptyState.icon"
      :title="emptyState.title"
      :description="emptyState.description"
    >
      <template v-if="emptyState.action !== undefined" #action>
        <component :is="emptyState.action" />
      </template>
      <template v-if="emptyState.secondaryAction !== undefined" #secondaryAction>
        <component :is="emptyState.secondaryAction" />
      </template>
    </EmptyState>
    <Table
      v-else
      :label="label"
      :caption="label"
      :stickyHeader="stickyHeader"
      :grid="true"
      :multiselectable="selectable"
    >
      <TableHead>
        <TableRow>
          <TableHeader v-if="selectable">
            <Checkbox
              :aria-label="messages.selectAll"
              :checked="headerChecked"
              :disabled="loading || ids.length === 0"
              @checkedChange="toggleAll()"
            />
          </TableHeader>
          <TableHeader v-if="expandable">
            <span :class="styles.expandLabel" data-undrawn="">
              {{ detailsLabel(undefined) }}
            </span>
          </TableHeader>
          <template v-for="column in columns" :key="column.key">
            <TableHeader
              :numeric="column.numeric"
              :sortable="column.sortable"
              :sortDirection="sort?.key === column.key ? sort?.direction : undefined"
              @sort="column.sortable && emit('sortChange', sortTo(column))"
            >
              {{ column.header }}
            </TableHeader>
          </template>
        </TableRow>
      </TableHead>
      <TableBody>
        <template v-if="loading">
          <template v-for="index in skeletons" :key="`skeleton-${index}`">
            <TableRow>
              <TableCell v-if="selectable">
                <Skeleton shape="circle" :size="4" />
              </TableCell>
              <TableCell v-if="expandable">
                <Skeleton shape="circle" :size="4" />
              </TableCell>
              <template v-for="column in columns" :key="column.key">
                <TableCell :numeric="column.numeric">
                  <Skeleton textStep="sm" />
                </TableCell>
              </template>
            </TableRow>
          </template>
        </template>
        <template v-else>
          <template v-for="(row, index) in data" :key="getRowId(row)">
            <TableRow
              :selected="selection?.has(getRowId(row))"
              :interactive="listening.rowClick"
              @click="listening.rowClick && emit('rowClick', row)"
            >
              <TableCell v-if="selectable">
                <span :class="styles.selectCell" @click="$event.stopPropagation()">
                  <Checkbox
                    :aria-label="getRowLabel?.(row) ?? messages.selectRow"
                    :checked="selection?.has(getRowId(row)) ?? false"
                    @checkedChange="toggleRow(getRowId(row))"
                  />
                </span>
              </TableCell>
              <TableCell v-if="expandable">
                <span
                  v-if="canExpand(row)"
                  :class="styles.expandCell"
                  @click="$event.stopPropagation()"
                >
                  <Button
                    variant="ghost"
                    tone="neutral"
                    size="sm"
                    :iconOnly="true"
                    :icon="canExpand(row) && open.has(getRowId(row)) ? 'up' : 'down'"
                    :label="detailsLabel(getRowName?.(row))"
                    :expanded="canExpand(row) && open.has(getRowId(row))"
                    :aria-controls="
                      canExpand(row) && open.has(getRowId(row))
                        ? `${uid}-detail-${index}`
                        : undefined
                    "
                    @click="toggleExpanded(getRowId(row))"
                  />
                </span>
              </TableCell>
              <template v-for="column in columns" :key="column.key">
                <TableCell :numeric="column.numeric">
                  <template v-if="typeof cellOf(column, row) === 'string'">{{
                    cellOf(column, row)
                  }}</template>
                  <template v-else>
                    <component :is="cellOf(column, row)" />
                  </template>
                </TableCell>
              </template>
            </TableRow>
            <!-- detail row -->
            <tr
              v-if="expandable && canExpand(row) && open.has(getRowId(row))"
              :id="`${uid}-detail-${index}`"
              data-detail=""
            >
              <td :class="styles.detailCell" :colspan="span">
                <div :class="styles.detail">
                  <slot name="rowDetail" :row="row" :close="() => closeDetail(getRowId(row))" />
                </div>
              </td>
            </tr>
          </template>
        </template>
      </TableBody>
    </Table>
    <!-- pagination row -->
    <div v-if="$slots.pagination" :class="styles.pagination">
      <Inline :gap="3" justify="end" :wrap="true">
        <slot name="pagination" />
      </Inline>
    </div>
  </div>
</template>
